void Tarjan(vector<int> g[vNum],int v){
    memset(dfn,0,sizeof(dfn));
    memset(instk,0,sizeof(instk));
    cnt=bcnt=0;
    while(!stk.empty()) stk.pop();
    for(int i=1;i<=v;i++)
        if(!dfn[i]) dfs(g,i);
}

