            t=t->lc;
            delete tmp;
        }
        else {
            tmp=t->rc; //情形(4)
            while(tmp->lc) tmp=tmp->lc;
            //获取t的直接后继tmp(右子树的最左孩子,算法中的(2))
            keytype k1=tmp->key;
            bst_delete(t,k1); //删除tmp
            t->key=k1; //用tmp的键值取代t的键值
        }
        return true;
    }
