rbTree RR(rbTree A);

//设置颜色,最多可设置三个结点
void set_color(rbTree t1,color c1,rbTree t2=NULL,color c2=RED,rbTree t3=NULL,color c3=RED){
    if(t1) t1->c=c1;
    if(t2) t2->c=c2;
