        if(succ){
            if(--tmp->cnt==0) //回退时,如果删除成功,则调整结点的cnt
                delete tmp,tmp=NULL;
            if(dep==0 && --t->cnt==0) //根结点特别处理
                delete t,t=NULL;
        }
    }
    else{
        succ=0;
        return 0;
    }
    return ret;
}

