void delete2_3_first(tree2_3 &rt,tree2_3 &t){
    if(t==NULL) return;

    tree2_3 removed=t; //t可能引用父结点的孩子槽，移动槽位前保存原指针
    //已有下溢的父结点 num==0 时只调整结构，不再减为 -1
    if(t->num>0){
        for(int i=0;i<t->num-1;i++) t->key[i]=t->key[i+1];
        t->num--;
    }
    if(t->num>0) return; //删除后仍为2-结点,结束

    //以下处理t中没有键值的情形
    if(t==rt){
        //根结点没有键值
        rt=t->child[0];
        if(rt!=NULL) rt->parent=NULL;
        delete removed;
        return;
    }

    tree2_3 tp=t->parent;
    int i=0;
    while(i<=tp->num && tp->child[i]!=t) i++;
    if(i>tp->num) return;

    //情形(2.1):左兄弟为3-结点
    if(i>0 && tp->child[i-1]->num>1){
        tree2_3 tb=tp->child[i-1];

        t->key[0]=tp->key[i-1];
        tp->key[i-1]=tb->key[tb->num-1];

        t->child[1]=t->child[0];
        t->child[0]=tb->child[tb->num];

        if(t->child[0]!=NULL)
            t->child[0]->parent=t;

        tb->child[tb->num]=NULL;
        t->num=1;
        tb->num--;
    }
        //情形(2.1):右兄弟为3-结点
    else if(i<tp->num && tp->child[i+1]->num>1){
        tree2_3 tb=tp->child[i+1];

        t->key[0]=tp->key[i];
        tp->key[i]=tb->key[0];

        t->child[1]=tb->child[0];
        if(t->child[1]!=NULL)
            t->child[1]->parent=t;

        for(int j=0;j<tb->num-1;j++)
            tb->key[j]=tb->key[j+1];

        for(int j=0;j<tb->num;j++)
            tb->child[j]=tb->child[j+1];

        tb->child[tb->num]=NULL;
        t->num=1;
        tb->num--;
    }
        //情形(2.2):父结点为3-结点,与兄弟合并
    else if(tp->num>1){
        if(i>0){
            tree2_3 tb=tp->child[i-1];

            tb->key[1]=tp->key[i-1];
            tb->child[2]=t->child[0];

            if(tb->child[2]!=NULL)
                tb->child[2]->parent=tb;

            tb->num=2;

            for(int j=i-1;j<tp->num-1;j++)
                tp->key[j]=tp->key[j+1];

            for(int j=i;j<tp->num;j++)
                tp->child[j]=tp->child[j+1];

            tp->child[tp->num]=NULL;
            tp->num--;
        }
        else{
            tree2_3 tb=tp->child[1];

            tb->key[1]=tb->key[0];
            tb->key[0]=tp->key[0];

            tb->child[2]=tb->child[1];
            tb->child[1]=tb->child[0];
            tb->child[0]=t->child[0];

            if(tb->child[0]!=NULL)
                tb->child[0]->parent=tb;

            tb->num=2;
            tp->key[0]=tp->key[1];
            tp->child[0]=tb;
            tp->child[1]=tp->child[2];
            tp->child[2]=NULL;
            tp->num--;
        }

        delete removed;
    }
        //情形(2.3):父结点为2-结点,合并后向上调整
    else{
        tree2_3 tb;

        if(i>0){
            //t为右分支,与左兄弟合并
            tb=tp->child[0];

            tb->key[1]=tp->key[0];
            tb->child[2]=t->child[0];

            if(tb->child[2]!=NULL)
                tb->child[2]->parent=tb;

            tb->num=2;
            delete removed;
        }
        else{
            //t为左分支,与右兄弟合并
            tb=tp->child[1];

            tb->key[1]=tb->key[0];
            tb->key[0]=tp->key[0];

            tb->child[2]=tb->child[1];
            tb->child[1]=tb->child[0];
            tb->child[0]=t->child[0];

            if(tb->child[0]!=NULL)
                tb->child[0]->parent=tb;

            tb->num=2;
            delete removed;
        }

        tp->child[0]=tb;
        tp->child[1]=NULL;
        tb->parent=tp;
        tp->num=0;

        //继续检查父结点
        if(tp==rt){
            rt=tb;
            tb->parent=NULL;
            delete tp;
        }
        else{
            delete2_3_first(rt,tp);
        }
    }
